import{_ as o,o as t,c as i,ae as n}from"./chunks/framework.vXWZTEWX.js";const h=JSON.parse('{"title":"ADR 018: Authentication Strategy Pivot (Popup vs Redirect)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/018-auth-strategy-pivot.md","filePath":"adr/018-auth-strategy-pivot.md"}'),a={name:"adr/018-auth-strategy-pivot.md"};function r(s,e,c,l,d,u){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-018-authentication-strategy-pivot-popup-vs-redirect" tabindex="-1">ADR 018: Authentication Strategy Pivot (Popup vs Redirect) <a class="header-anchor" href="#adr-018-authentication-strategy-pivot-popup-vs-redirect" aria-label="Permalink to &quot;ADR 018: Authentication Strategy Pivot (Popup vs Redirect)&quot;">​</a></h1><ul><li>Status: superseded by <a href="./040-google-oauth-pkce.html">ADR 040</a> (implicit grant → PKCE)</li><li>Deciders: Elena (Lead Developer), Antigravity (AI Assistant)</li><li>Date: 2026-03-04</li></ul><h2 id="context-and-problem-statement" tabindex="-1">Context and Problem Statement <a class="header-anchor" href="#context-and-problem-statement" aria-label="Permalink to &quot;Context and Problem Statement&quot;">​</a></h2><p>Integrating Google Authentication (OIDC) into the React Frontend hosted on Render presented a critical conflict with browser security policies. The application requires a secure environment, but Google&#39;s &quot;Popup&quot; sign-in flow (<code>ux_mode: &#39;popup&#39;</code>) relies on <code>window.opener</code> communication. Modern browsers, enforcing <code>Cross-Origin-Opener-Policy (COOP)</code>, were blocking this communication (<code>window.closed</code> error), treating the popup as untrusted verification. Despite relaxing headers to <code>unsafe-none</code> and <code>same-origin-allow-popups</code>, the issue persisted in the production environment (deployment v1.0.5 - v1.0.9).</p><h2 id="decision-drivers" tabindex="-1">Decision Drivers <a class="header-anchor" href="#decision-drivers" aria-label="Permalink to &quot;Decision Drivers&quot;">​</a></h2><ul><li><strong>Reliability</strong>: Authentication must work 100% of the time for all users, regardless of browser privacy settings.</li><li><strong>Security Standards</strong>: We should not disable core security features (COOP/COEP) just to make a popup work.</li><li><strong>User Experience</strong>: While popups are &quot;smoother&quot;, a broken popup is a blocker. A redirect is robust.</li></ul><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li><strong>Option 1: Relax COOP Headers (Tried)</strong>: Attempted to set <code>Cross-Origin-Opener-Policy: unsafe-none</code>. <ul><li><em>Result</em>: Failed. Google&#39;s SDK still detected isolation issues or the header propagation was inconsistent on the CDN.</li></ul></li><li><strong>Option 2: Proxy Auth</strong>: Route auth through the backend exclusively. <ul><li><em>Result</em>: Too complex for the current timeline.</li></ul></li><li><strong>Option 3: Redirect Mode (<code>ux_mode: &#39;redirect&#39;</code>)</strong>: Use full-page navigation to Google and back.</li></ul><h2 id="decision-outcome" tabindex="-1">Decision Outcome <a class="header-anchor" href="#decision-outcome" aria-label="Permalink to &quot;Decision Outcome&quot;">​</a></h2><p>Chosen option: <strong>Option 3: Redirect Mode</strong>.</p><p>We switched the <code>@react-oauth/google</code> configuration to <code>ux_mode: &#39;redirect&#39;</code>. Instead of opening a child window, the entire app redirects to <code>accounts.google.com</code>. Upon return, the application parses the <code>access_token</code> from the URL hash (Implicit Flow).</p><h3 id="positive-consequences" tabindex="-1">Positive Consequences <a class="header-anchor" href="#positive-consequences" aria-label="Permalink to &quot;Positive Consequences&quot;">​</a></h3><ul><li><strong>Bypasses COOP/COEP</strong>: Full page navigation is not subject to Opener Policy restrictions in the same way.</li><li><strong>Universal Compatibility</strong>: Works on mobile browsers and aggressive privacy extensions where popups are often blocked.</li><li><strong>Simplified Troubleshooting</strong>: Removes &quot;race conditions&quot; between window checks.</li></ul><h3 id="negative-consequences" tabindex="-1">Negative Consequences <a class="header-anchor" href="#negative-consequences" aria-label="Permalink to &quot;Negative Consequences&quot;">​</a></h3><ul><li><strong>State Loss</strong>: The React app reloads completely upon return, requiring session restoration (handled by <code>AuthContext</code>).</li><li><strong>UX Friction</strong>: Slightly more disruptive than a popup, but acceptable for a login action.</li></ul><h2 id="implementation-details" tabindex="-1">Implementation Details <a class="header-anchor" href="#implementation-details" aria-label="Permalink to &quot;Implementation Details&quot;">​</a></h2><ul><li><code>GoogleLoginButton.tsx</code>: Added logic to check <code>window.location.hash</code> for <code>access_token</code> on mount.</li><li><code>main.tsx</code>: Version bumped to v1.1.0 to track this release.</li></ul>',17)])])}const g=o(a,[["render",r]]);export{h as __pageData,g as default};
